import {useMemo} from 'react';

import type {TrackerSelectItem, TrackerSelectItemValueBase} from '../types';

export function useSelectedItemsIds<Value extends TrackerSelectItemValueBase>(
    selectedItems?: Array<string | TrackerSelectItem<Value>>,
): string[] {
    return useMemo(
        () =>
            selectedItems?.map((itemData) =>
                typeof itemData === 'string' ? itemData : String(itemData.id),
            ) || [],
        [selectedItems],
    );
}
